package com.wedo.backend.task.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="tasks") public class TaskEntity { @Id private UUID id; @Column(name="activity_id",nullable=false) private UUID activityId; @Column(name="created_by") private UUID createdBy; @Column(nullable=false) private String title; @Column private String description; @Enumerated(EnumType.STRING) @Column(nullable=false) private TaskStatus status; @Column(name="due_at") private Instant dueAt; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected TaskEntity(){} public TaskEntity(UUID id,UUID activityId,UUID createdBy,String title,String description,Instant dueAt,Instant now){this.id=id;this.activityId=activityId;this.createdBy=createdBy;this.title=title;this.description=description;this.status=TaskStatus.TODO;this.dueAt=dueAt;this.createdAt=now;this.updatedAt=now;} public UUID getId(){return id;} public UUID getActivityId(){return activityId;} public UUID getCreatedBy(){return createdBy;} public String getTitle(){return title;} public String getDescription(){return description;} public TaskStatus getStatus(){return status;} public Instant getDueAt(){return dueAt;} public Instant getCreatedAt(){return createdAt;} public void update(String title,String description,Instant dueAt,Instant now){this.title=title;this.description=description;this.dueAt=dueAt;this.updatedAt=now;} public TaskStatus changeStatus(TaskStatus next,Instant now){TaskStatus before=status;status=next;updatedAt=now;return before;} }
